  IF v_type IS DISTINCT FROM 'jsonb' OR v_null IS DISTINCT FROM 'YES' OR v_def IS DISTINCT FROM NULL THEN
    problems := problems || format('column verification_event.payload_json: %s / %s / %s, expected jsonb / YES / %s',
                                   coalesce(v_type, 'MISSING'), coalesce(v_null, '-'), coalesce(v_def, 'no default'), coalesce(NULL, 'no default'));
  END IF;
  v_type := NULL; v_null := NULL; v_def := NULL;
  SELECT data_type, is_nullable, column_default INTO v_type, v_null, v_def FROM information_schema.columns
   WHERE table_schema = 'public' AND table_name = 'verification_event' AND column_name = 'created_at';
  IF v_type IS DISTINCT FROM 'timestamp with time zone' OR v_null IS DISTINCT FROM 'NO' OR v_def IS DISTINCT FROM 'now()' THEN
    problems := problems || format('column verification_event.created_at: %s / %s / %s, expected timestamp with time zone / NO / %s',
                                   coalesce(v_type, 'MISSING'), coalesce(v_null, '-'), coalesce(v_def, 'no default'), coalesce('now()', 'no default'));
  END IF;
  -- Indexes, including every uniqueness rule the code relies on.
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_user_period_unique'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_user_period_unique ON public.invoices USING btree (user_id, period_start, period_end) WHERE (stripe_invoice_id IS NULL)' THEN
    problems := problems || format('index idx_invoices_user_period_unique: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_user_period_unique'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_stripe_invoice_id'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_stripe_invoice_id ON public.invoices USING btree (stripe_invoice_id) WHERE (stripe_invoice_id IS NOT NULL)' THEN
    problems := problems || format('index idx_invoices_stripe_invoice_id: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_stripe_invoice_id'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_gocardless_payment_id'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_gocardless_payment_id ON public.invoices USING btree (gocardless_payment_id) WHERE (gocardless_payment_id IS NOT NULL)' THEN
    problems := problems || format('index idx_invoices_gocardless_payment_id: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_gocardless_payment_id'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_provider_payment_id'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_provider_payment_id ON public.invoices USING btree (provider_payment_id) WHERE (provider_payment_id IS NOT NULL)' THEN
    problems := problems || format('index idx_invoices_provider_payment_id: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_provider_payment_id'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_seq_year'), 'MISSING') <> 'CREATE UNIQUE INDEX idx_invoices_seq_year ON public.invoices_seq USING btree (year)' THEN
    problems := problems || format('index idx_invoices_seq_year: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_invoices_seq_year'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'subscription_user_unique'), 'MISSING') <> 'CREATE UNIQUE INDEX subscription_user_unique ON public.subscription USING btree (user_id)' THEN
    problems := problems || format('index subscription_user_unique: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'subscription_user_unique'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_created'), 'MISSING') <> 'CREATE INDEX idx_notification_user_created ON public.notification USING btree (user_id, created_at DESC)' THEN
    problems := problems || format('index idx_notification_user_created: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_created'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_created_at'), 'MISSING') <> 'CREATE INDEX idx_notification_created_at ON public.notification USING btree (created_at DESC)' THEN
    problems := problems || format('index idx_notification_created_at: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_created_at'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_read'), 'MISSING') <> 'CREATE INDEX idx_notification_user_read ON public.notification USING btree (user_id, read)' THEN
    problems := problems || format('index idx_notification_user_read: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_read'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_unread'), 'MISSING') <> 'CREATE INDEX idx_notification_user_unread ON public.notification USING btree (user_id) WHERE (read_at IS NULL)' THEN
    problems := problems || format('index idx_notification_user_unread: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_notification_user_unread'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'login_throttle_pkey'), 'MISSING') <> 'CREATE UNIQUE INDEX login_throttle_pkey ON public.login_throttle USING btree (key)' THEN
    problems := problems || format('index login_throttle_pkey: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'login_throttle_pkey'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_login_throttle_first_failure_at'), 'MISSING') <> 'CREATE INDEX idx_login_throttle_first_failure_at ON public.login_throttle USING btree (first_failure_at)' THEN
    problems := problems || format('index idx_login_throttle_first_failure_at: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_login_throttle_first_failure_at'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'mail_audit_pkey'), 'MISSING') <> 'CREATE UNIQUE INDEX mail_audit_pkey ON public.mail_audit USING btree (id)' THEN
    problems := problems || format('index mail_audit_pkey: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'mail_audit_pkey'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_mail_audit_item_created'), 'MISSING') <> 'CREATE INDEX idx_mail_audit_item_created ON public.mail_audit USING btree (item_id, created_at DESC)' THEN
    problems := problems || format('index idx_mail_audit_item_created: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_mail_audit_item_created'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'forward_audit_pkey'), 'MISSING') <> 'CREATE UNIQUE INDEX forward_audit_pkey ON public.forward_audit USING btree (id)' THEN
    problems := problems || format('index forward_audit_pkey: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'forward_audit_pkey'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'fwd_audit_mail_created'), 'MISSING') <> 'CREATE INDEX fwd_audit_mail_created ON public.forward_audit USING btree (mail_item_id, created_at DESC)' THEN
    problems := problems || format('index fwd_audit_mail_created: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'fwd_audit_mail_created'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'verification_event_pkey'), 'MISSING') <> 'CREATE UNIQUE INDEX verification_event_pkey ON public.verification_event USING btree (id)' THEN
    problems := problems || format('index verification_event_pkey: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'verification_event_pkey'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_verification_event_created_at'), 'MISSING') <> 'CREATE INDEX idx_verification_event_created_at ON public.verification_event USING btree (created_at)' THEN
    problems := problems || format('index idx_verification_event_created_at: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_verification_event_created_at'), 'MISSING'));
  END IF;
  IF coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_verification_event_subject'), 'MISSING') <> 'CREATE INDEX idx_verification_event_subject ON public.verification_event USING btree (subject_type, subject_id)' THEN
    problems := problems || format('index idx_verification_event_subject: %s', coalesce((SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_verification_event_subject'), 'MISSING'));
  END IF;
  -- Constraints.
  FOR k IN SELECT unnest(ARRAY['login_throttle', 'mail_audit', 'forward_audit', 'verification_event']) LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = format('public.%I', k)::regclass AND contype = 'p') THEN
      problems := problems || format('table %s has no primary key', k);
    END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.verification_event'::regclass AND contype = 'c'
                 AND pg_get_constraintdef(oid) = 'CHECK ((subject_type = ANY (ARRAY[''user''::text, ''business_owner''::text])))') THEN
    problems := problems || text 'verification_event subject_type check is missing or different';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.subscription'::regclass AND contype = 'c') THEN
    problems := problems || text 'subscription still has a check constraint (the mandate check blocks Stripe activations)';
  END IF;
  -- Data.
  SELECT count(*) INTO n FROM "user" u WHERE NOT u.is_admin AND u.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM business b WHERE b.user_id = u.id);
  IF n > 0 THEN problems := problems || format('%s customer(s) still without a business', n); END IF;
  SELECT count(*) INTO n FROM (SELECT year FROM invoices_seq GROUP BY year HAVING count(*) > 1) d;
  IF n > 0 THEN problems := problems || text 'invoices_seq has duplicated years'; END IF;
  -- Migration tracking: each Phase 1 migration recorded exactly once.
  FOR k IN SELECT unnest(ARRAY['20261115_01_notification_and_audit_tables.sql', '20261115_02_backfill_primary_business.sql', '20261115_03_stripe_entitlement.sql', '20261115_04_invoice_period_unique_for_internal_only.sql', '20261117_01_login_throttle.sql']::text[]) LOOP
    SELECT count(*) INTO n FROM migrations WHERE name = k;
    IF n <> 1 THEN problems := problems || format('migrations table: %s recorded %s time(s)', k, n); END IF;
  END LOOP;
  IF cardinality(problems) > 0 THEN
    RAISE EXCEPTION 'VERIFY FAILED (% problem(s)):%', cardinality(problems), E'\n  - ' || array_to_string(problems, E'\n  - ');
  END IF;
  RAISE NOTICE 'VERIFY PASSED';
END
$verify$;
ROLLBACK;
\echo 'VERIFY PASSED: tables, columns, types, constraints, unique rules, indexes and tracking are as required.'
